text:
{
  "nl_intent": "In my 6G private campus network, ensure ultra-reliable low-latency communication for 500 industrial robots with end-to-end latency below 1 ms and reliability of 99.9999% while keeping energy consumption under 500 kWh per day.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "URLLC-Robots-Campus",
    "description": "Ultra-reliable low-latency intent for industrial robots in 6G campus",
    "expression": {
      "@type": "tio:IntentExpression",
      "@baseType": "IntentExpression",
      "iri": "tio:expression-uuid-001",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:Slice",
          "name": "URLLC-Robots"
        },
        "latency": {
          "value": 1,
          "unit": "ms"
        },
        "reliability": 0.999999
      }
    },
    "priority": "high",
    "context": "6G-campus-industrial",
    "lifecycleStatus": "active",
    "version": "1.0"
  },
  "notes": "Classic URLLC 6G use-case; matches TR290 DeliveryExpectation"
}

{
  "nl_intent": "For the AI-orchestrated 6G core in my campus, minimize total energy consumption of all network functions while maintaining at least 10 Gbps aggregate throughput and 99.99% availability.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Energy-Aware-Core",
    "description": "Energy minimization with QoS guardrails",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-002",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:NFSet",
          "name": "Core-NFs"
        },
        "throughput": {
          "value": 10,
          "unit": "Gbps"
        },
        "availability": 0.9999
      },
      "icm:UtilityFunction": {
        "name": "minEnergy",
        "weight": 0.8
      }
    },
    "priority": "medium",
    "context": "6G-energy-optimization",
    "lifecycleStatus": "active"
  },
  "notes": "Energy vs performance trade-off; uses utility function per TR290"
}

{
  "nl_intent": "Deploy a new eMBB slice for 2000 AR/VR users in the 6G campus with guaranteed 500 Mbps per user and 99.999% reliability, but only if it does not exceed 30% of total RAN resources.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "eMBB-ARVR-Slice",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-003",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:Slice",
          "name": "eMBB-ARVR"
        },
        "throughputPerUser": {
          "value": 500,
          "unit": "Mbps"
        },
        "reliability": 0.99999
      },
      "icm:Constraint": {
        "resourceLimit": "30% RAN"
      }
    },
    "priority": "high",
    "context": "6G-campus-eMBB",
    "lifecycleStatus": "active"
  },
  "notes": "Resource-constrained slicing"
}

{
  "nl_intent": "In case of detected congestion in the 6G campus RAN, automatically reconfigure mMTC slices for 10000 IoT sensors to reduce their duty cycle to 10% while preserving 99.9% packet delivery ratio.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Congestion-mMTC-Adapt",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-004",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:Slice",
          "name": "mMTC-IoT"
        },
        "dutyCycle": 0.1,
        "deliveryRatio": 0.999
      }
    },
    "priority": "medium",
    "context": "6G-congestion-response",
    "lifecycleStatus": "active"
  },
  "notes": "Dynamic adaptation intent"
}

{
  "nl_intent": "Ensure predictive assurance for all critical 6G URLLC slices: any predicted latency violation >0.5 ms must trigger proactive resource reallocation within 100 ms.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Predictive-Assurance-URLLC",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-005",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:Slice",
          "name": "URLLC-Critical"
        },
        "proactiveAction": "reallocate",
        "latencyThreshold": 0.5,
        "reactionTime": 100
      }
    },
    "priority": "high",
    "context": "6G-predictive",
    "lifecycleStatus": "active"
  },
  "notes": "Assurance-focused with timing"
}

{
  "nl_intent": "Create two conflicting intents: one for maximum throughput in eMBB and one for minimum energy; resolve via negotiation with priority to energy if carbon budget is exceeded.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Conflict-Energy-vs-Throughput",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-006",
      "icm:DeliveryExpectation": [
        {
          "target": "eMBB",
          "throughput": "max"
        },
        {
          "target": "Core",
          "energy": "min"
        }
      ],
      "icm:NegotiationRule": {
        "priority": "energy",
        "condition": "carbonBudgetExceeded"
      }
    },
    "priority": "high",
    "context": "6G-conflict-negotiation",
    "lifecycleStatus": "active"
  },
  "notes": "Explicit conflict example for testing negotiation"
}

{
  "nl_intent": "In the 6G multi-domain campus (RAN + transport + core), guarantee end-to-end latency <2 ms for 100 autonomous vehicles with 99.9999% reliability across all domains.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "MultiDomain-V2X-URLLC",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-007",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:EndToEndPath"
        },
        "latency": 2,
        "reliability": 0.999999
      }
    },
    "priority": "critical",
    "context": "6G-multi-domain",
    "lifecycleStatus": "active"
  },
  "notes": "Cross-domain 6G V2X"
}

{
  "nl_intent": "For my 6G testbed, report on intent fulfillment every 5 minutes and notify if any KPI deviates more than 5% from target.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Intent-Reporting-Testbed",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-008",
      "icm:ReportingExpectation": {
        "interval": "5m",
        "deviationThreshold": 0.05
      }
    },
    "priority": "medium",
    "context": "6G-testbed-monitoring",
    "lifecycleStatus": "active"
  },
  "notes": "Reporting intent per TR290"
}

{
  "nl_intent": "Suspend all non-critical slices in the 6G campus during a power outage alert while preserving URLLC slices at full capacity.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Power-Outage-Priority",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-009",
      "icm:DeliveryExpectation": {
        "target": "URLLC",
        "action": "preserve"
      },
      "icm:Constraint": {
        "target": "non-critical",
        "action": "suspend"
      }
    },
    "priority": "critical",
    "context": "6G-resilience",
    "lifecycleStatus": "active"
  },
  "notes": "Lifecycle / conditional intent"
}

{
  "nl_intent": "Optimize 6G RAN beamforming for 99.99% coverage in the campus while limiting total transmit power to 40 dBm per site.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Beamforming-Power-Opt",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-010",
      "icm:DeliveryExpectation": {
        "target": {
          "@type": "sli:RANBeam"
        },
        "coverage": 0.9999,
        "txPowerLimit": {
          "value": 40,
          "unit": "dBm"
        }
      }
    },
    "priority": "medium",
    "context": "6G-RAN-optimization",
    "lifecycleStatus": "active"
  },
  "notes": "RAN-specific 6G optimization"
}

{
  "nl_intent": "Ensure zero-touch failover for all 6G intents: if any intent report shows degradation, automatically migrate to backup resources within 50 ms.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Zero-Touch-Failover",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-011",
      "icm:DeliveryExpectation": {
        "target": "AllIntents",
        "failoverTime": 50,
        "action": "migrate"
      }
    },
    "priority": "high",
    "context": "6G-autonomy",
    "lifecycleStatus": "active"
  },
  "notes": "Autonomous closed-loop"
}

{
  "nl_intent": "In the 6G campus, allow dynamic negotiation between two intents: one for maximum user density and one for minimum interference; accept the compromise that maximizes overall utility.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Negotiation-Density-vs-Interference",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-012",
      "icm:NegotiationRule": {
        "parameters": [
          "userDensity",
          "interference"
        ],
        "objective": "maxUtility"
      }
    },
    "priority": "medium",
    "context": "6G-negotiation",
    "lifecycleStatus": "active"
  },
  "notes": "Negotiation test case"
}

{
  "nl_intent": "Provide a partial intent for testing: guarantee only reliability >99.999% for URLLC robots; all other KPIs are best-effort.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Partial-Intent-URLLC",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-013",
      "icm:DeliveryExpectation": {
        "target": "URLLC-Robots",
        "reliability": 0.99999,
        "otherKPIs": "bestEffort"
      }
    },
    "priority": "low",
    "context": "6G-partial-spec",
    "lifecycleStatus": "active"
  },
  "notes": "Partial specification edge case"
}

{
  "nl_intent": "For AI-native 6G orchestration, translate this natural language request into a valid TMF921 intent that can be directly posted to the /intent endpoint.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "AI-Orchestration-Meta",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-014",
      "icm:DeliveryExpectation": {
        "target": "Orchestrator",
        "action": "translateNLtoTMF921"
      }
    },
    "priority": "medium",
    "context": "6G-AI-meta",
    "lifecycleStatus": "active"
  },
  "notes": "Meta-intent for your own pipeline"
}

{
  "nl_intent": "Monitor and report fulfillment of all active intents in the 6G campus every 60 seconds via the hub subscription mechanism.",
  "tmf921_intent": {
    "@type": "Intent",
    "name": "Continuous-Monitoring",
    "expression": {
      "@type": "tio:IntentExpression",
      "iri": "tio:expression-uuid-015",
      "icm:ReportingExpectation": {
        "interval": "60s",
        "channel": "hub"
      }
    },
    "priority": "medium",
    "context": "6G-monitoring",
    "lifecycleStatus": "active"
  },
  "notes": "Hub + reporting integration"
}
